            jbig2_decode_mmr_consume(mmr, 6);
            b1 = jbig2_find_changing_element_of_color(ref, a0, mmr->width, !c);
            if (b1 < 2)
                break;
            if (c) {
                if (a0 == MINUS1 || b1 - 2 < a0)
                    return -1;
                jbig2_set_bits(dst, a0, b1 - 2);
